#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-08

# Gate for the pi adapter (#4001).
#
# Two arms, and the script always says which one ran:
#
#   REAL   pi is installed, so pi's OWN resolver runs against this tree
#          (tests/plugins/pi/check-loader.mjs). Only this arm can catch pi
#          changing its resolution rules under us.
#   RULES  pi is absent, which is CI. The same resolution is re-derived from
#          pi's documented rules (tests/plugins/pi/check-rules.py). A green
#          RULES run is weaker than a green REAL run and prints as such.
#
# What both arms assert: the `pi` key in package.json resolves to EXACTLY the
# repo's SKILL.md set. Before #4001 that count was 0 and nothing errored, which
# is why the assertion is an equality and not a "> 0".
#
# The check bodies live in tests/plugins/pi/ rather than in heredocs: bash 5.3
# can back a heredoc with a pipe and write before the reader exists, which
# deadlocks with no output and no timeout (ork#3348).
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"
HELPERS="$SCRIPT_DIR/pi"
MCP_MANIFEST="$PROJECT_ROOT/tests/agents/mcp-servers.manifest.json"
MCP_EXAMPLE="$PROJECT_ROOT/.pi/mcp.json.example"

fail() { echo "FAIL: $*"; exit 1; }

# ── 1. The pi manifest contract ────────────────────────────────────────────
python3 "$HELPERS/check-manifest.py" "$PROJECT_ROOT"

# ── 2. The expected count, taken from the tree ─────────────────────────────
EXPECTED="$(find "$PROJECT_ROOT/src/skills" -name SKILL.md -type f | wc -l | tr -d ' ')"
[[ "$EXPECTED" -gt 0 ]] || fail "no SKILL.md under src/skills; the expectation itself is broken"

BUILT="$(find "$PROJECT_ROOT/plugins/ork/skills" -name SKILL.md -type f | wc -l | tr -d ' ')"
[[ "$BUILT" == "$EXPECTED" ]] \
  || fail "plugins/ork/skills has $BUILT skills, src/skills has $EXPECTED; run npm run build"

# ── 3. Resolution, through pi where possible ───────────────────────────────
# find-pi-root.py prints the package root or nothing, always exiting 0: an
# absent pi is a supported state, not a failure.
ARM="RULES"
PI_ROOT="$(python3 "$HELPERS/find-pi-root.py")"

if [[ -n "$PI_ROOT" && -f "$PI_ROOT/dist/core/package-manager.js" ]]; then
  ARM="REAL"
  PI_PKG="$PI_ROOT" REPO="$PROJECT_ROOT" EXPECTED="$EXPECTED" \
    node "$HELPERS/check-loader.mjs"
else
  python3 "$HELPERS/check-rules.py" "$PROJECT_ROOT" "$EXPECTED"
fi

# ── 4. The MCP allowlist template ──────────────────────────────────────────
[[ -f "$MCP_EXAMPLE" ]] || fail "missing $MCP_EXAMPLE"
python3 "$HELPERS/check-mcp-template.py" "$MCP_EXAMPLE" "$MCP_MANIFEST"

# The live copy must be ignored: it is the file a user pastes a token into.
git -C "$PROJECT_ROOT" check-ignore -q .pi/mcp.json \
  || fail ".pi/mcp.json is not gitignored; a copied template could commit a token"

if [[ "$ARM" == "REAL" ]]; then
  echo "PASS: pi adapter, arm=REAL (pi resolved $EXPECTED skills, 0 diagnostics) + MCP template"
  echo "      pi package root: $PI_ROOT"
else
  echo "PASS: pi adapter, arm=RULES ($EXPECTED skills by pi 0.85 rules) + MCP template"
  echo "NOTE: RULES cannot detect an upstream pi rule change. Install pi to run the REAL arm."
fi
